defmodule Ros2Zenoh.FoxgloveMsgs.Msg.CircleAnnotation do
  @moduledoc """
  The definition of `foxglove_msgs/CircleAnnotation`, which the
  `ImageAnnotations` schema names. `ImageAnnotations.circles` is always
  empty here, so it has no codec.
  """

  alias Ros2Zenoh.BuiltinInterfaces.Msg.Time
  alias Ros2Zenoh.FoxgloveMsgs.Msg.{Color, KeyValuePair, Point2}

  def msg_definition do
    """
    # foxglove_msgs/msg/CircleAnnotation
    # A circle annotation on a 2D image

    # Generated by https://github.com/foxglove/foxglove-sdk

    # Timestamp of circle
    builtin_interfaces/Time timestamp

    # Center of the circle in 2D image coordinates (pixels).
    # The coordinate uses the top-left corner of the top-left pixel of the image as the origin.
    foxglove_msgs/Point2 position

    # Circle diameter in pixels
    float64 diameter

    # Line thickness in pixels
    float64 thickness

    # Fill color
    foxglove_msgs/Color fill_color

    # Outline color
    foxglove_msgs/Color outline_color

    # Additional user-provided metadata associated with this annotation. Keys must be unique.
    foxglove_msgs/KeyValuePair[] metadata
    """
  end

  def dependencies,
    do: [
      Time,
      Point2,
      Color,
      KeyValuePair
    ]
end
